@Test
void oppositeLockOrderOrdersCompleteWithinTwoSeconds() throws Exception {
    inventory.register(10L, 10);
    inventory.register(22L, 10);

    ExecutorService executor = Executors.newFixedThreadPool(2);
    CountDownLatch ready = new CountDownLatch(2);
    CountDownLatch start = new CountDownLatch(1);

    try {
        Future<?> first = executor.submit(() -> {
            ready.countDown();
            start.await();
            orderService.createOrder(1L, List.of(
                    new OrderItem(10L, 1),
                    new OrderItem(22L, 1)));
            return null;
        });
        Future<?> second = executor.submit(() -> {
            ready.countDown();
            start.await();
            orderService.createOrder(2L, List.of(
                    new OrderItem(22L, 1),
                    new OrderItem(10L, 1)));
            return null;
        });

        assertTrue(ready.await(1, TimeUnit.SECONDS));
        start.countDown();

        first.get(2, TimeUnit.SECONDS);
        second.get(2, TimeUnit.SECONDS);

        assertEquals(8, inventory.countOf(10L));
        assertEquals(8, inventory.countOf(22L));
    } finally {
        executor.shutdownNow();
    }
}
